// BstNode redefined to allow whitebox testing
typedef struct BstNode BstNode;
struct BstNode {
  void* key;
  void* data;
  BstNode* child_left;
  BstNode* child_right;
  int height;
  int balance;
};

// AI generated by: Antigravity / Gemini 3.8 Flash
// Prompt: "Edit test_bst.c to resolve strdup not working in Windows. Create a
// helper function heapStr(const char* src): char* newStr =
// TRY_MALLOC(strlen(src) + 1); strcpy(newStr, src); Replace every occurrence of
// strdup with heapStr helper." Changes: Added heapStr helper function and
// replaced all occurrences of strdup with heapStr to resolve strdup not working
// in Windows

static Ctx* test_ctx = NULL;

static char* heapStr(const char* src) {
  Ctx* ctx = test_ctx;
  char* newStr = TRY_MALLOC(strlen(src) + 1);
  strcpy(newStr, src);
  return newStr;
}

